# MAGIC %md ## 2. Enforced constraints (CHECK), and informational keys (PK/FK, Unity Catalog only)

# COMMAND ----------

CHECKS = [
    ('players', 'ck_players_kyc_status', "kyc_status IN ('not_started','pending','verified','rejected')"),
    ('players', 'ck_players_status', "status IN ('active','blocked','self_excluded','closed')"),
    ('wallets', 'ck_wallet_nonneg', 'real_balance >= 0 AND bonus_balance >= 0'),
    ('wallet_transactions', 'ck_wallet_transactions_txn_type', "txn_type IN ('deposit','withdrawal','bet_stake','bet_win','bonus_credit', 'bonus_debit','refund','reversal','manual_adjustment')"),
    ('wallet_transactions', 'ck_wallet_transactions_balance_type', "balance_type IN ('real','bonus')"),
    ('wallet_transactions', 'ck_wallet_transactions_direction', "direction IN ('credit','debit')"),
    ('wallet_transactions', 'ck_wallet_transactions_status', "status IN ('posted','reversed')"),
    ('deposit_attempts', 'ck_deposit_attempts_status', "status IN ('initiated','success','failed')"),
    ('withdrawal_requests', 'ck_withdrawal_requests_status', "status IN ('requested','approved','paid','failed','cancelled')"),
    ('bets', 'ck_bets_product', "product IN ('sportsbook','casino','retail')"),
    ('bets', 'ck_bets_channel', "channel IN ('web','app','retail')"),
    ('bets', 'ck_bets_status', "status IN ('open','won','lost','void','cashed_out')"),
    ('bets', 'ck_bets_stake_nonneg', 'stake_real_amount >= 0 AND stake_bonus_amount >= 0'),
    ('sports_bet_details', 'ck_sports_bet_details_bet_class', "bet_class IN ('single','accumulator')"),
    ('bet_legs', 'ck_bet_legs_leg_result', "leg_result IN ('pending','won','lost','void')"),
    ('bonus_campaigns', 'ck_bonus_campaigns_campaign_type', "campaign_type IN ('registration','deposit_match','cashback','free_spins','other')"),
    ('player_bonuses', 'ck_player_bonuses_status', "status IN ('active','completed','expired','forfeited')"),
]     # (table, constraint name, expression): ENUM values and the MySQL CHECKs
for table, name, expr in CHECKS:
    spark.sql(f"ALTER TABLE {table} ADD CONSTRAINT {name} CHECK ({expr})")
print(f"{len(CHECKS)} CHECK constraints added (enforced on every write)")

