# MAGIC %md ## 5. Duplicate-free: every primary key and natural key; referential integrity: every foreign key

# COMMAND ----------

KEYS = [
    ('affiliates', ['affiliate_code'], 'unique'),
    ('affiliates', ['affiliate_id'], 'primary key'),
    ('players', ['player_id'], 'primary key'),
    ('player_identity', ['email'], 'unique'),
    ('player_identity', ['player_id'], 'primary key'),
    ('player_vip_tier_history', ['player_id', 'valid_from_utc'], 'primary key'),
    ('player_tag_history', ['player_id', 'tag', 'valid_from_utc'], 'unique'),
    ('player_tag_history', ['tag_history_id'], 'primary key'),
    ('wallets', ['player_id', 'currency'], 'unique'),
    ('wallets', ['wallet_id'], 'primary key'),
    ('wallet_transactions', ['idempotency_key'], 'unique'),
    ('wallet_transactions', ['wallet_txn_id'], 'primary key'),
    ('payment_methods', ['method_code'], 'unique'),
    ('payment_methods', ['method_id'], 'primary key'),
    ('deposit_attempts', ['gateway_ref'], 'unique'),
    ('deposit_attempts', ['deposit_attempt_id'], 'primary key'),
    ('withdrawal_requests', ['request_id'], 'unique'),
    ('withdrawal_requests', ['withdrawal_id'], 'primary key'),
    ('bets', ['request_id'], 'unique'),
    ('bets', ['bet_id'], 'primary key'),
    ('sports_events', ['sport', 'league', 'home_team', 'away_team', 'starts_at_utc'], 'unique'),
    ('sports_events', ['event_id'], 'primary key'),
    ('sports_bet_details', ['bet_id'], 'primary key'),
    ('bet_legs', ['bet_id', 'event_id', 'market'], 'unique'),
    ('bet_legs', ['leg_id'], 'primary key'),
    ('game_providers', ['name'], 'unique'),
    ('game_providers', ['provider_id'], 'primary key'),
    ('games', ['provider_id', 'name'], 'unique'),
    ('games', ['game_id'], 'primary key'),
    ('casino_round_details', ['game_id', 'provider_round_ref'], 'unique'),
    ('casino_round_details', ['bet_id'], 'primary key'),
    ('retail_locations', ['name', 'address_city'], 'unique'),
    ('retail_locations', ['location_id'], 'primary key'),
    ('devices', ['fingerprint'], 'unique'),
    ('devices', ['device_id'], 'primary key'),
    ('retail_bet_details', ['location_id', 'ticket_number'], 'unique'),
    ('retail_bet_details', ['bet_id'], 'primary key'),
    ('bonus_campaigns', ['name', 'valid_from_utc'], 'unique'),
    ('bonus_campaigns', ['campaign_id'], 'primary key'),
    ('player_bonuses', ['player_bonus_id'], 'primary key'),
    ('bonus_rollover_events', ['player_bonus_id', 'bet_id'], 'unique'),
    ('bonus_rollover_events', ['rollover_event_id'], 'primary key'),
]            # (table, [columns], 'primary key' | 'unique')
FKS = [
    ('players', ['affiliate_id'], 'affiliates', ['affiliate_id']),
    ('player_identity', ['player_id'], 'players', ['player_id']),
    ('player_vip_tier_history', ['player_id'], 'players', ['player_id']),
    ('player_tag_history', ['player_id'], 'players', ['player_id']),
    ('wallets', ['player_id'], 'players', ['player_id']),
    ('wallet_transactions', ['wallet_id'], 'wallets', ['wallet_id']),
    ('wallet_transactions', ['player_id'], 'players', ['player_id']),
    ('wallet_transactions', ['reversal_of_wallet_txn_id'], 'wallet_transactions', ['wallet_txn_id']),
    ('deposit_attempts', ['player_id'], 'players', ['player_id']),
    ('deposit_attempts', ['method_id'], 'payment_methods', ['method_id']),
    ('withdrawal_requests', ['player_id'], 'players', ['player_id']),
    ('withdrawal_requests', ['method_id'], 'payment_methods', ['method_id']),
    ('bets', ['player_id'], 'players', ['player_id']),
    ('sports_bet_details', ['bet_id'], 'bets', ['bet_id']),
    ('bet_legs', ['bet_id'], 'bets', ['bet_id']),
    ('bet_legs', ['event_id'], 'sports_events', ['event_id']),
    ('games', ['provider_id'], 'game_providers', ['provider_id']),
    ('casino_round_details', ['bet_id'], 'bets', ['bet_id']),
    ('casino_round_details', ['game_id'], 'games', ['game_id']),
    ('retail_bet_details', ['bet_id'], 'bets', ['bet_id']),
    ('retail_bet_details', ['location_id'], 'retail_locations', ['location_id']),
    ('retail_bet_details', ['device_id'], 'devices', ['device_id']),
    ('player_bonuses', ['player_id'], 'players', ['player_id']),
    ('player_bonuses', ['campaign_id'], 'bonus_campaigns', ['campaign_id']),
    ('bonus_rollover_events', ['player_bonus_id'], 'player_bonuses', ['player_bonus_id']),
    ('bonus_rollover_events', ['bet_id'], 'bets', ['bet_id']),
    ('wallet_transactions', ['related_deposit_attempt_id'], 'deposit_attempts', ['deposit_attempt_id']),
    ('wallet_transactions', ['related_withdrawal_id'], 'withdrawal_requests', ['withdrawal_id']),
    ('wallet_transactions', ['related_bet_id'], 'bets', ['bet_id']),
    ('wallet_transactions', ['related_player_bonus_id'], 'player_bonuses', ['player_bonus_id']),
]              # (child table, [columns], parent table, [columns])

key_rows = []
for table, cols, kind in KEYS:
    c = ", ".join(cols)
    dupes = spark.sql(f"SELECT COUNT(*) FROM (SELECT {c} FROM {table} GROUP BY {c} HAVING COUNT(*) > 1)").first()[0]
    key_rows.append((table, kind, c, dupes))
fk_rows = []
for child, ccols, parent, pcols in FKS:
    on = " AND ".join(f"c.{a} = p.{b}" for a, b in zip(ccols, pcols))
    notnull = " AND ".join(f"c.{a} IS NOT NULL" for a in ccols)
    orphans = spark.sql(f"SELECT COUNT(*) FROM {child} c LEFT ANTI JOIN {parent} p ON {on} WHERE {notnull}").first()[0]
    fk_rows.append((f"{child}({', '.join(ccols)})", f"{parent}({', '.join(pcols)})", orphans))

display(spark.createDataFrame(key_rows, "table STRING, key STRING, columns STRING, duplicate_keys BIGINT"))
display(spark.createDataFrame(fk_rows, "foreign_key STRING, references STRING, orphan_rows BIGINT"))
check(all(r[3] == 0 for r in key_rows), f"no duplicates on any of the {len(key_rows)} primary and natural keys")
check(all(r[2] == 0 for r in fk_rows), f"no orphans on any of the {len(fk_rows)} foreign keys")

